mapper.select:
SELECT * FROM shopion.tPrfEstimt

    AND CompCode = #{pCompCode}
    AND BranchId = #{pBranchId}
    AND DeptCode = #{pDeptCode}
    AND AccntId = #{pAccntId}

     AND StartDate <= DATE_FORMAT(#{pStartDate}, '%Y%m%d') 


     AND EndDate >= ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) 


LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*) FROM shopion.tPrfEstimt

    AND CompCode = #{pCompCode}
    AND BranchId = #{pBranchId}
    AND DeptCode = #{pDeptCode}
    AND AccntId = #{pAccntId}

     AND StartDate <= DATE_FORMAT(#{pStartDate}, '%Y%m%d') 


     AND EndDate >= ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)

SELECT * FROM shopion.tPrfEstimt
WHERE CompCode = #{compCode} AND BranchId = #{branchId} AND DeptCode = #{deptCode}
AND AccntId = #{accntId} AND StartDate = #{startDate} AND EndDate = #{endDate}

mapper.update:
UPDATE shopion.tPrfEstimt SET
    EstimtAmt = #{estimtAmt}, State = #{state}, Remark = #{remark},
    ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE CompCode = #{compCode} AND BranchId = #{branchId} AND DeptCode = #{deptCode}
AND AccntId = #{accntId} AND StartDate = #{startDate} AND EndDate = #{endDate}

mapper.delete:
DELETE FROM shopion.tPrfEstimt
WHERE CompCode = #{compCode} AND BranchId = #{branchId} AND DeptCode = #{deptCode}
AND AccntId = #{accntId} AND StartDate = #{startDate} AND EndDate = #{endDate}
